#include <mmt_core.h>
#include <stdint.h>
#include <string.h>

static int em_is_dicom(const void *data) {
    proto_hierarchy_t *p = (proto_hierarchy_t *) data;
    int i;
    for (i = 0; i < p->len; i++)
        if (p->proto_path[i] == 701)
            return 1;
    return 0;
}

/* ---- PDU boundary tracker ---- */
#define PDU_TRACK_SLOTS    4096 /* power of 2 */
#define PDU_TRACK_PROBES   8
#define PDU_TRACK_MAX_SKIP (16u << 20) /* an A-ASSOCIATE further away starts a new stream */
#define PDU_AT_BOUNDARY    1 /* the segment starts at a PDU boundary */
#define PDU_FLAGGED        2 /* a header this rule flags starts in the segment */

/* the header this rule flags */
static inline int pdu_track_bad(uint8_t type, uint32_t len) {
    (void) type; (void) len;
    return 0;
}

typedef struct {
    uint32_t src, dst, ports;
    uint32_t next;   /* TCP sequence number of the next PDU header */
    uint64_t last;   /* 0: free slot */
    int synced;
} pdu_track_t;

static pdu_track_t pdu_tracks[PDU_TRACK_SLOTS];
static uint64_t pdu_track_tick = 0;
/* the last segment seen, so that a rule evaluating it twice gets the same answer */
static struct { uint32_t src, dst, ports, seq, n; int result; } pdu_track_memo;

static pdu_track_t *pdu_track_lookup(uint32_t src, uint32_t dst, uint32_t ports) {
    uint32_t h = (src * 2654435761u) ^ (dst * 2246822519u) ^ (ports * 3266489917u), i;
    pdu_track_t *victim = NULL, *p;
    for (i = 0; i < PDU_TRACK_PROBES; i++) {
        p = &pdu_tracks[(h + i) & (PDU_TRACK_SLOTS - 1)];
        if (p->last != 0 && p->src == src && p->dst == dst && p->ports == ports)
            return p;
        if (victim == NULL || p->last < victim->last)
            victim = p;
    }
    memset(victim, 0, sizeof(*victim));
    victim->src = src;
    victim->dst = dst;
    victim->ports = ports;
    return victim;
}

/*
 * Follow the PDU stream of one direction of a TCP connection; return PDU_AT_BOUNDARY
 * and/or PDU_FLAGGED. dpi_pdu_type is dicom.pdu_type: 1..7 when mmt-dpi accepted a
 * PDU header at the start of the segment, 0 otherwise.
 */
static int pdu_track(const void *ip_src, const void *ip_dst, double sport, double dport,
                     double seq_nb, const void *payload, double payload_len, double dpi_pdu_type) {
    const uint8_t *p = (const uint8_t *) payload;
    uint32_t src, dst, ports, seq = (uint32_t) seq_nb, n = (uint32_t) payload_len, len;
    int64_t off;
    int result = 0;
    pdu_track_t *d;

    if (ip_src == NULL || ip_dst == NULL || p == NULL || n == 0)
        return 0;
    memcpy(&src, ip_src, sizeof(src));
    memcpy(&dst, ip_dst, sizeof(dst));
    ports = ((uint32_t) sport << 16) | (uint32_t) dport;
    if (pdu_track_memo.src == src && pdu_track_memo.dst == dst && pdu_track_memo.ports == ports
            && pdu_track_memo.seq == seq && pdu_track_memo.n == n)
        return pdu_track_memo.result;

    d = pdu_track_lookup(src, dst, ports);
    d->last = ++pdu_track_tick;
    off = (int32_t)(d->next - seq);
    if (dpi_pdu_type == 1 || dpi_pdu_type == 2) {
        /* an A-ASSOCIATE-RQ/AC accepted by mmt-dpi starts (or restarts) the stream,
         * unless it lies inside the PDU being followed */
        if (!d->synced || off < 0 || off > PDU_TRACK_MAX_SKIP) {
            d->synced = 1;
            off = 0;
        }
    }
    if (!d->synced) {
        result = 0;
    } else if (off < 0) {
        d->synced = 0; /* the data before this segment was not seen */
    } else {
        if (off == 0)
            result |= PDU_AT_BOUNDARY;
        while (off + 6 <= n) {
            len = ((uint32_t)p[off + 2] << 24) | ((uint32_t)p[off + 3] << 16)
                | ((uint32_t)p[off + 4] << 8) | p[off + 5];
            if (pdu_track_bad(p[off], len))
                result |= PDU_FLAGGED;
            off += 6 + (int64_t) len;
        }
        if (off < n || off > 0x7FFFFFFF)
            d->synced = 0; /* a header split across segments, or an absurd length */
        else
            d->next = seq + (uint32_t) off;
    }

    pdu_track_memo.src = src;
    pdu_track_memo.dst = dst;
    pdu_track_memo.ports = ports;
    pdu_track_memo.seq = seq;
    pdu_track_memo.n = n;
    pdu_track_memo.result = result;
    return result;
}

static int em_pdu_at_boundary(const void *ip_src, const void *ip_dst, double sport, double dport,
                              double seq_nb, const void *payload, double payload_len, double dpi_pdu_type) {
    return (pdu_track(ip_src, ip_dst, sport, dport, seq_nb, payload, payload_len, dpi_pdu_type)
            & PDU_AT_BOUNDARY) != 0;
}

static int em_pdu_hdr_check(const void *ip_src, const void *ip_dst, double sport, double dport,
                            double seq_nb, const void *payload, double payload_len, double dpi_pdu_type) {
    return (pdu_track(ip_src, ip_dst, sport, dport, seq_nb, payload, payload_len, dpi_pdu_type)
            & PDU_FLAGGED) != 0;
}
/* ---- end of PDU boundary tracker ---- */

#include <stdint.h>
#include <string.h>

#define AE_SWAP_SLOTS  1024 /* power of 2 */
#define AE_SWAP_PROBES 8

typedef struct {
    uint32_t src, dst;
    uint64_t last;          /* 0: free slot */
    char called[17], calling[17];
} ae_swap_pair_t;

static ae_swap_pair_t ae_swap_pairs[AE_SWAP_SLOTS];
static uint64_t ae_swap_tick = 0;

/* Trim trailing spaces from AE title into dst (max 16 chars) */
static void trim_ae(char *dst, const char *src) {
    int i;
    if (src == NULL) { dst[0] = '\0'; return; }
    for (i = 0; i < 16 && src[i] != '\0'; i++)
        dst[i] = src[i];
    dst[i] = '\0';
    /* Remove trailing spaces */
    for (i = i - 1; i >= 0 && dst[i] == ' '; i--)
        dst[i] = '\0';
}

static int em_check_ae_swap(const void *ip_src, const void *ip_dst, const char *called, const char *calling) {
    char c1[17], c2[17];
    uint32_t src, dst, h, i;
    ae_swap_pair_t *p = NULL, *victim = NULL, *q;

    if (ip_src == NULL || ip_dst == NULL || called == NULL || calling == NULL)
        return 0;
    memcpy(&src, ip_src, sizeof(src));
    memcpy(&dst, ip_dst, sizeof(dst));
    trim_ae(c1, called);
    trim_ae(c2, calling);
    ae_swap_tick++;

    h = (src * 2654435761u) ^ (dst * 2246822519u);
    for (i = 0; i < AE_SWAP_PROBES; i++) {
        q = &ae_swap_pairs[(h + i) & (AE_SWAP_SLOTS - 1)];
        if (q->last != 0 && q->src == src && q->dst == dst) {
            p = q;
            break;
        }
        if (victim == NULL || q->last < victim->last)
            victim = q;
    }

    /* First association of this directed pair: record baseline */
    if (p == NULL) {
        victim->src = src;
        victim->dst = dst;
        memcpy(victim->called, c1, sizeof(c1));
        memcpy(victim->calling, c2, sizeof(c2));
        victim->last = ae_swap_tick;
        return 0;
    }
    p->last = ae_swap_tick;

    /* Swap: current called matches baseline calling AND vice versa */
    if (strcmp(c1, p->calling) == 0 && strcmp(c2, p->called) == 0 &&
        strcmp(c1, c2) != 0)
        return 1;

    return 0;
}
